    #[case("/p/node_modules/x/index.d.ts", "BackgroundProps", "bg", Why::StyleType)]
    #[case("/p/node_modules/x/index.d.ts", "Props", "m", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "ColorsProps", "m", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "StylePropsExtra", "m", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "className", Why::GlobalAttribute)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "aria-label", Why::GlobalAttribute)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "data-testid", Why::GlobalAttribute)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "tabIndex", Why::GlobalAttribute)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "value", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "defaultValue", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "type", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "name", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "disabled", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "Aria-label", Why::DependencyApi)]
    fn the_clause_that_decides_is_the_first_that_fits(
        #[case] file: &str,
        #[case] type_name: &str,
        #[case] prop: &str,
        #[case] expected: Why,
    ) {
        assert_eq!(classify(file, type_name, prop), expected);
    }

    #[test]
    fn only_clauses_one_to_three_collapse_a_source() {
        assert!(is_ambient_source("/p/node_modules/@types/react/index.d.ts", "X"));
