// Prints the TS classifier's verdict for every distinct (layer file, layer type, prop) a collapsed layer names in the given
// canonical JSON outputs, as the parity fixture the Rust test reads. Usage: node gen_parity.mts out.json in1.json ...
import { readFileSync, writeFileSync } from 'node:fs'
import { classify, layerOnly } from './src/layer-only.ts'

const [out, ...inputs] = process.argv.slice(2)
const seen = new Map<string, any>()
for (const input of inputs) {
  const caliper = JSON.parse(readFileSync(input, 'utf8'))
  for (const item of layerOnly(caliper)) {
    // Machine paths are not part of the rule: keep from the last node_modules on, under a fixed root.
    const at = item.layerFile.lastIndexOf('/node_modules/')
    const file = at === -1 ? item.layerFile : `/p${item.layerFile.slice(at)}`
    const { kind, why } = classify({ layer: item.layer, layerFile: file, prop: item.prop })
    const key = `${file}\u0000${item.layer}\u0000${item.prop}`
    if (!seen.has(key)) seen.set(key, { file, type: item.layer, prop: item.prop, kind, why })
  }
}
const rows = [...seen.values()].sort(
  (a, b) => a.file.localeCompare(b.file) || a.type.localeCompare(b.type) || a.prop.localeCompare(b.prop),
)
writeFileSync(out, JSON.stringify(rows, null, 1) + '\n')
const byWhy = Object.groupBy(rows, (r) => r.why)
console.log(rows.length, Object.fromEntries(Object.entries(byWhy).map(([k, v]) => [k, v!.length])))

