// Lists the distinct collapsed layers of canonical JSON outputs: type, size, file tail, how many components carry it, verdict.
import { readFileSync } from 'node:fs'
import { classify } from './src/layer-only.ts'

for (const input of process.argv.slice(2)) {
  const caliper = JSON.parse(readFileSync(input, 'utf8'))
  const layers = new Map<string, any>()
  for (const component of Object.values<any>(caliper.components)) {
    for (const layer of component.inheritance ?? []) {
      if (layer.htmlElement) continue
      const key = `${layer.fileName}\u0000${layer.typeName}`
      const entry = layers.get(key) ?? { type: layer.typeName, size: layer.totalProps, file: String(layer.fileName), n: 0 }
      entry.n++
      layers.set(key, entry)
    }
  }
  console.log(`== ${input.split('/').pop()}: ${layers.size} distinct collapsed layers`)
  for (const l of [...layers.values()].sort((a, b) => b.n - a.n)) {
    const at = l.file.lastIndexOf('/node_modules/')
    const file = at === -1 ? l.file : l.file.slice(at + 14)
    const probe = classify({ layer: l.type, layerFile: at === -1 ? l.file : `/p${l.file.slice(at)}`, prop: 'zzz' })
    console.log(`  ${String(l.n).padStart(5)}x ${String(l.size).padStart(4)} props  ${l.type}  [${probe.why}]  ${file}`)
  }
}

