  ...['ButtonHTMLAttributes', 'AriaLabelingAttributes', 'Aria_Attributes', 'AriaAttributesExtra', 'Aria-Attributes', 'AriaAttributes2'].map(
    (t): [string, string, string] => [pkg, t, 'foo'],
