//! Which inherited dependency sources are ambient: what every element has, or a style system, which a controls table
//! would not lead with. The resolver collapses these into a layer (names only) and lists every other dependency
//! source, which is the API a dependency's component exposes (its modes, state and composition).
//!
//! The rule reads only the source's file, its type name and a prop's name, never its size. It is the rule measured in
//! `docs/measurement.md` ("Layer-only props"); `apps/oracle/src/layer-only.ts` is the classifier the measurement ran,
//! and `tests/collapse_relevance_parity.rs` keeps this module equal to it. The first clause that fits decides:
//!
//! 1. **dom file**: the source's file is `@types/react`, or react-aria's `@react-types/shared/src/dom.d.ts`
//! 2. **dom type**: the source's type is a DOM family: `GlobalDOMEvents`, `DOMAttributes`, `AriaAttributes`,
//!    `AllHTMLAttributes`, `SVGAttributes`, `*HTMLAttributes`, `Aria*Attributes`
//! 3. **style type**: the source's type is a style system: `*StyleProps`, `*StyleProp`, `SystemProps`,
//!    `Space|Layout|Color|Typography|Border|Flex|Grid|Position|Shadow|Background` + `Props`
//! 4. **global attribute**: the prop is one every element has, or starts `aria-` or `data-`
//! 5. **dependency api**: anything else
//!
//! Clauses 1 to 3 decide a whole source, so they decide whether it collapses. Clause 4 decides a prop of a source the
//! first three did not match; it never collapses a source on its own.

/// The attributes every element has, which no component's API is about. `defaultValue`, `value`, `type`, `name` and
/// the like are not here: they are element-specific, and a dependency's component often uses them as its own API.
#[cfg(test)]
const GLOBAL_ATTRIBUTES: &[&str] = &[
    "className",
    "style",
    "id",
    "title",
    "lang",
    "dir",
    "hidden",
    "tabIndex",
    "role",
    "slot",
    "accessKey",
    "draggable",
    "contentEditable",
    "spellCheck",
    "translate",
    "inputMode",
    "nonce",
];

/// Type names of the DOM families that are named exactly (the rest end in `HTMLAttributes` or are `Aria*Attributes`).
const DOM_TYPES: &[&str] = &["GlobalDOMEvents", "DOMAttributes", "AriaAttributes", "AllHTMLAttributes", "SVGAttributes"];

/// The style-system prefixes that, with `Props`, name a style source (`SpaceProps`, `LayoutProps`, ...).
const STYLE_PREFIXES: &[&str] =
    &["Space", "Layout", "Color", "Typography", "Border", "Flex", "Grid", "Position", "Shadow", "Background"];

/// Which clause of the rule decided. Only the parity test with the oracle's classifier reads the per-prop verdict; the
/// resolver needs the whole-source clauses (`is_ambient_source`).
#[cfg(test)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Why {
    /// The source's file is a DOM declaration file (clause 1).
    DomFile,
    /// The source's type is a DOM family (clause 2).
    DomType,
    /// The source's type is a style system (clause 3).
    StyleType,
    /// The prop is one every element has (clause 4).
    GlobalAttribute,
    /// None of the above: a dependency's own API (clause 5).
    DependencyApi,
}

#[cfg(test)]
impl Why {
    /// Whether the prop is ambient (clauses 1 to 4) and not API (clause 5).
    pub(crate) fn is_ambient(self) -> bool {
        self != Self::DependencyApi
    }
}

/// `\w*` in the rule: letters, digits and underscore.
fn is_word(text: &str) -> bool {
    text.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
}

fn is_dom_file(file: &str) -> bool {
    file.contains("/@types/react/")
        || file
            .rsplit_once("/@react-types/shared/src/")
            .is_some_and(|(_, name)| matches!(name, "dom.d.ts" | "dom.d.mts" | "dom.d.cts"))
}

fn is_dom_type(type_name: &str) -> bool {
    DOM_TYPES.contains(&type_name)
        || type_name.strip_suffix("HTMLAttributes").is_some_and(is_word)
        || type_name.strip_prefix("Aria").and_then(|rest| rest.strip_suffix("Attributes")).is_some_and(is_word)
}

fn is_style_type(type_name: &str) -> bool {
    type_name == "SystemProps"
        || type_name.strip_suffix("StyleProps").or_else(|| type_name.strip_suffix("StyleProp")).is_some_and(is_word)
        || STYLE_PREFIXES.iter().any(|prefix| type_name.strip_prefix(prefix) == Some("Props"))
}

/// Whether `prop` is one every element has, or an `aria-` or `data-` attribute (clause 4).
#[cfg(test)]
fn is_global_attribute(prop: &str) -> bool {
    GLOBAL_ATTRIBUTES.contains(&prop) || prop.starts_with("aria-") || prop.starts_with("data-")
}

/// Whether a source in `file` declaring the type `type_name` is ambient as a whole (clauses 1 to 3), so the resolver
/// records it as a layer of names instead of listing its props.
pub(crate) fn is_ambient_source(file: &str, type_name: &str) -> bool {
    is_dom_file(file) || is_dom_type(type_name) || is_style_type(type_name)
}

/// The rule for one prop a collapsed source names: the clause that decided and so whether it is ambient or API.
#[cfg(test)]
pub(crate) fn classify(file: &str, type_name: &str, prop: &str) -> Why {
    if is_dom_file(file) {
        Why::DomFile
    } else if is_dom_type(type_name) {
        Why::DomType
    } else if is_style_type(type_name) {
        Why::StyleType
    } else if is_global_attribute(prop) {
        Why::GlobalAttribute
    } else {
        Why::DependencyApi
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use rstest::rstest;

    #[rstest]
    #[case("/p/node_modules/@types/react/index.d.ts", "Anything", "foo", Why::DomFile)]
    #[case("/p/node_modules/@react-types/shared/src/dom.d.ts", "GlobalDOMEvents", "onClick", Why::DomFile)]
    #[case("/p/node_modules/@react-types/shared/src/dom.d.mts", "Other", "x", Why::DomFile)]
    #[case("/p/node_modules/@react-types/shared/src/events.d.ts", "KeyboardEvents", "onKeyDown", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "GlobalDOMEvents", "onClick", Why::DomType)]
    #[case("/p/node_modules/x/index.d.ts", "DOMAttributes", "onClick", Why::DomType)]
    #[case("/p/node_modules/x/index.d.ts", "AriaAttributes", "aria-label", Why::DomType)]
    #[case("/p/node_modules/x/index.d.ts", "AllHTMLAttributes", "href", Why::DomType)]
    #[case("/p/node_modules/x/index.d.ts", "SVGAttributes", "d", Why::DomType)]
    #[case("/p/node_modules/x/index.d.ts", "HTMLAttributes", "dir", Why::DomType)]
    #[case("/p/node_modules/x/index.d.ts", "ButtonHTMLAttributes", "type", Why::DomType)]
    #[case("/p/node_modules/x/index.d.ts", "AriaLabelingAttributes", "aria-label", Why::DomType)]
    #[case("/p/node_modules/x/index.d.ts", "AriaAttributesExtra", "foo", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "Aria_Attributes", "foo", Why::DomType)]
    #[case("/p/node_modules/x/index.d.ts", "Aria-Attributes", "foo", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "StyleProps", "margin", Why::StyleType)]
    #[case("/p/node_modules/x/index.d.ts", "JsxStyleProps", "margin", Why::StyleType)]
    #[case("/p/node_modules/x/index.d.ts", "ViewStyleProp", "margin", Why::StyleType)]
    #[case("/p/node_modules/x/index.d.ts", "SystemProps", "margin", Why::StyleType)]
    #[case("/p/node_modules/x/index.d.ts", "SpaceProps", "m", Why::StyleType)]
    #[case("/p/node_modules/x/index.d.ts", "BackgroundProps", "bg", Why::StyleType)]
    #[case("/p/node_modules/x/index.d.ts", "Props", "m", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "ColorsProps", "m", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "StylePropsExtra", "m", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "className", Why::GlobalAttribute)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "aria-label", Why::GlobalAttribute)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "data-testid", Why::GlobalAttribute)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "tabIndex", Why::GlobalAttribute)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "value", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "defaultValue", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "type", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "name", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "disabled", Why::DependencyApi)]
    #[case("/p/node_modules/x/index.d.ts", "DialogProps", "Aria-label", Why::DependencyApi)]
    fn the_clause_that_decides_is_the_first_that_fits(
        #[case] file: &str,
        #[case] type_name: &str,
        #[case] prop: &str,
        #[case] expected: Why,
    ) {
        assert_eq!(classify(file, type_name, prop), expected);
    }

    #[test]
    fn only_clauses_one_to_three_collapse_a_source() {
        assert!(is_ambient_source("/p/node_modules/@types/react/index.d.ts", "X"));
        assert!(is_ambient_source("/p/node_modules/x/index.d.ts", "GlobalDOMEvents"));
        assert!(is_ambient_source("/p/node_modules/x/index.d.ts", "SystemProps"));
        // A source of global attributes only is not collapsed on its own: clause 4 decides a prop, not a source.
        assert!(!is_ambient_source("/p/node_modules/x/index.d.ts", "DialogProps"));
    }
}

